// B.Pharm course catalogue (PCI 2026 syllabus), generated by
// scripts/parse-syllabus.ts and seeded into the Course tables. Zod-checked on load.
import { z } from "zod";
import seed from "./bpharm-2026.json" with { type: "json" };

const marks = z.number().int().min(0);
const minutes = z.number().int().positive();

export const catalogueCourseSchema = z.object({
  /** As printed; elective options keep their suffix, e.g. "BP607T AEC1". */
  code: z.string().regex(/^BP\d{3}(?:T|P|I|RP)(?: (?:AEC|SEC|VAC)\d)?$/),
  title: z.string().min(1).max(200),
  semester: z.number().int().min(1).max(8),
  courseKind: z.enum(["THEORY", "PRACTICAL", "PROJECT", "INTERNSHIP"]),
  credits: z.number().int().min(1).max(10),
  lectureHrs: z.number().int().min(0),
  tutorialHrs: z.number().int().min(0),
  practicalHrs: z.number().int().min(0),
  maxHours: z.number().int().positive().nullable(),
  maxMarks: marks,
  continuousMarks: marks,
  sessionalMarks: marks,
  sessionalMinutes: minutes.nullable(),
  endSemMarks: marks,
  endSemMinutes: minutes,
  ruleSetId: z.string().nullable(),
  electiveOf: z.string().nullable(),
  electiveLabel: z.string().nullable(),
  syllabusPage: z.number().int().positive().nullable(),
  outcomes: z.array(z.object({ number: z.number().int().positive(), text: z.string().min(1) })),
  units: z.array(
    z.object({
      number: z.number().int().positive(),
      /** Empty when the syllabus gives the unit no heading. */
      title: z.string(),
      hours: z.number().positive(),
    }),
  ),
});
export type CatalogueCourse = z.infer<typeof catalogueCourseSchema>;

export const catalogueSchema = z.object({
  program: z.literal("B_PHARM"),
  source: z.object({
    document: z.string(),
    sha256: z.string().regex(/^[a-f0-9]{64}$/),
    pages: z.string(),
  }),
  /** Places where the syllabus PDF contradicts itself, with the PDF page. */
  discrepancies: z.array(
    z.object({ code: z.string().optional(), page: z.number().int(), text: z.string() }),
  ),
  courses: z.array(catalogueCourseSchema).min(1),
});
export type Catalogue = z.infer<typeof catalogueSchema>;

let cached: Catalogue | undefined;
export function bpharmCatalogue(): Catalogue {
  cached ??= catalogueSchema.parse(seed);
  return cached;
}

/** CO tag as printed on papers (D63): `BP604T.01`, `BP607T.01 AEC1`. */
export { coTag } from "../paper/co-tag.ts";
